# Drive libngspice from Python with ctypes: load a netlist, run, read vectors.
import ctypes as C, ctypes.util, os, sys

lib = C.CDLL(os.environ.get("NGSPICE_LIB") or ctypes.util.find_library("ngspice") or "libngspice.so.0")

# callback types from sharedspice.h
SendChar = C.CFUNCTYPE(C.c_int, C.c_char_p, C.c_int, C.c_void_p)
SendStat = C.CFUNCTYPE(C.c_int, C.c_char_p, C.c_int, C.c_void_p)
ControlledExit = C.CFUNCTYPE(C.c_int, C.c_int, C.c_bool, C.c_bool, C.c_int, C.c_void_p)
SendData = C.CFUNCTYPE(C.c_int, C.c_void_p, C.c_int, C.c_int, C.c_void_p)
SendInitData = C.CFUNCTYPE(C.c_int, C.c_void_p, C.c_int, C.c_void_p)
BGThreadRunning = C.CFUNCTYPE(C.c_int, C.c_bool, C.c_int, C.c_void_p)

log = []
@SendChar
def on_char(text, ident, user):
    log.append(text.decode(errors="replace"))
    return 0
@SendStat
def on_stat(text, ident, user):
    return 0
@ControlledExit
def on_exit(status, unload, quit, ident, user):
    return 0

class vector_info(C.Structure):
    _fields_ = [("v_name", C.c_char_p), ("v_type", C.c_int), ("v_flags", C.c_short),
                ("v_realdata", C.POINTER(C.c_double)), ("v_compdata", C.c_void_p),
                ("v_length", C.c_int)]
lib.ngGet_Vec_Info.restype = C.POINTER(vector_info)
lib.ngSpice_CurPlot.restype = C.c_char_p
lib.ngSpice_Init(on_char, on_stat, on_exit, None, None, None, None)

def cmd(s):
    return lib.ngSpice_Command(s.encode())

def load(lines):
    arr = (C.c_char_p * (len(lines) + 1))(*[l.encode() for l in lines], None)
    return lib.ngSpice_Circ(arr)

def vec(name):
    p = lib.ngGet_Vec_Info(name.encode())
    if not p:
        raise KeyError(name)
    v = p.contents
    return [v.v_realdata[i] for i in range(v.v_length)]

load(["RC from Python", "V1 in 0 PULSE(0 1 0 1n 1n 1 2)", "R1 in out 1k", "C1 out 0 1u", ".end"])
for r in ["1k", "2k", "4k"]:
    cmd(f"alter R1 {r}")
    cmd("tran 10u 5m")                       # runs in the foreground; bg_run for a background thread
    t, v = vec("time"), vec("v(out)")
    i63 = next(i for i, x in enumerate(v) if x >= 0.632)
    print(f"R1={r}: plot {lib.ngSpice_CurPlot().decode()}, tau = {t[i63]*1e3:.2f} ms")
